#include "stdlib/stats/base/ndarray/dztest.h"
#include "stdlib/stats/strided/dztest.h"
#include "stdlib/stats/base/ztest/one-sample/results/float64.h"
#include "stdlib/stats/base/ztest/alternatives.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdint.h>

/**
* Computes a one-sample Z-test for a one-dimensional double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional output ndarray containing a results object.
*     -   a zero-dimensional ndarray specifying the alternative hypothesis.
*     -   a zero-dimensional ndarray specifying the significance level.
*     -   a zero-dimensional ndarray specifying the mean under the null hypothesis.
*     -   a zero-dimensional ndarray specifying the known standard deviation.
*
* @param arrays    list containing ndarrays
*/
void stdlib_stats_dztest( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	// Resolve a pointer to the results object (a struct stored in a zero-dimensional ndarray having a user-defined data type):
	struct stdlib_stats_ztest_one_sample_float64_results *results = (struct stdlib_stats_ztest_one_sample_float64_results *)stdlib_ndarray_get_ptr( arrays[ 1 ], NULL );

	int8_t alternative;
	double alpha;
	double sigma;
	double mu;
	stdlib_ndarray_get_int8( arrays[ 2 ], NULL, &alternative );
	stdlib_ndarray_get_float64( arrays[ 3 ], NULL, &alpha );
	stdlib_ndarray_get_float64( arrays[ 4 ], NULL, &mu );
	stdlib_ndarray_get_float64( arrays[ 5 ], NULL, &sigma );

	API_SUFFIX(stdlib_strided_dztest_ndarray)( stdlib_ndarray_dimension( x, 0 ), (enum STDLIB_STATS_ZTEST_ALTERNATIVE)alternative, alpha, mu, sigma, (const double *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ), results );
}
